export function createIndex(){
  let rows=[],buckets=new Map();
  const areas=['North','South','East','West'];
  return{
    async load(size,changed){
      if(!Number.isInteger(size)||size<1)throw Error('Invalid data size');rows=[];buckets=new Map();
      for(let position=0;position<size;){
        const until=Math.min(position+2000,size);
        while(position<until){const row={id:position+1,customer:`Customer ${position%4096}`,region:areas[position%4],cents:position*7919%1000000,month:position%12+1};rows.push(row);const key=`${row.region}/${row.month}`;const bucket=buckets.get(key)||[];bucket.push(row);buckets.set(key,bucket);position++;}
        changed?.(position,size);await new Promise(resolve=>requestAnimationFrame(resolve));
      }
    },
    query(options={}){
      const {search='',region='',month='',sort='id-asc'}=options;
      const input=region&&month?(buckets.get(`${region}/${Number(month)}`)||[]):rows;
      const output=[];for(const row of input)if((!search||row.customer.includes(search))&&(!region||row.region===region)&&(!month||row.month===Number(month)))output.push(row);
      if(sort==='cents-desc')return output.sort((left,right)=>left.cents===right.cents?left.id-right.id:right.cents-left.cents);
      if(sort!=='id-asc')throw Error('Unknown sort');return output;
    },
  };
}
